import React, { useState, useEffect } from 'react';
import { dashboardApi } from '../api/client';
import SkeletonCard from './SkeletonCard';
import EmptyState from './EmptyState';
import { Layers } from 'lucide-react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';
import { Bar } from 'react-chartjs-2';

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

const ProductionChart = () => {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchProduction();
  }, []);

  const fetchProduction = async () => {
    try {
      setLoading(true);
      const res = await dashboardApi.getProduction();
      if (res.data.success) {
        setData(res.data.data);
      }
    } catch (err) {
      console.error('Failed to fetch production output:', err);
    } finally {
      setLoading(false);
    }
  };

  if (loading) return <SkeletonCard height="300px" />;
  if (!data || data.length === 0) {
    return (
      <div className="glass-card" style={{ padding: '1.5rem' }}>
        <h3 style={{ fontSize: '1.05rem', fontWeight: '700', marginBottom: '1rem', color: 'var(--text-primary)' }}>
          Production Output
        </h3>
        <EmptyState title="No Production Data" message="No fabric production records found for the last 7 days." />
      </div>
    );
  }

  // Extract unique dates and production lines
  const uniqueDates = [...new Set(data.map((d) => d.date))];
  const uniqueLines = [...new Set(data.map((d) => d.line))];

  const datasets = uniqueLines.map((lineName, idx) => {
    const lineData = uniqueDates.map((dateStr) => {
      const match = data.find((d) => d.date === dateStr && d.line === lineName);
      return match ? match.output : 0;
    });

    return {
      label: lineName,
      data: lineData,
      backgroundColor: idx === 0 ? '#10B981' : 'rgba(16, 185, 129, 0.45)',
      borderColor: '#10B981',
      borderWidth: 1,
      borderRadius: 4,
    };
  });

  const chartData = {
    labels: uniqueDates,
    datasets,
  };

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'top',
        align: 'end',
        labels: {
          color: '#94A3B8',
          font: { family: 'Plus Jakarta Sans', size: 11 },
          usePointStyle: true,
          boxWidth: 8,
        },
      },
      tooltip: {
        backgroundColor: '#131B2E',
        titleColor: '#FFFFFF',
        bodyColor: '#10B981',
        borderColor: '#1E293B',
        borderWidth: 1,
        padding: 10,
        callbacks: {
          label: (context) => `${context.dataset.label}: ${context.raw} meters`,
        },
      },
    },
    scales: {
      x: {
        grid: { display: false },
        ticks: { color: '#94A3B8', font: { family: 'Plus Jakarta Sans', size: 11 } },
      },
      y: {
        grid: { color: 'rgba(30, 41, 59, 0.6)', drawBorder: false },
        ticks: { color: '#94A3B8', font: { family: 'Plus Jakarta Sans', size: 11 } },
      },
    },
  };

  return (
    <div className="glass-card" style={{ padding: '1.5rem', display: 'flex', flexDirection: 'column' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem' }}>
        <div>
          <h3 style={{ fontSize: '1.05rem', fontWeight: '700', color: 'var(--text-primary)', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <Layers size={18} style={{ color: 'var(--status-running)' }} /> Daily Production Output
          </h3>
          <span style={{ fontSize: '0.78rem', color: 'var(--text-secondary)' }}>Fabric Output (Meters) per Production Line</span>
        </div>
      </div>
      <div style={{ height: '220px', width: '100%' }}>
        <Bar data={chartData} options={options} />
      </div>
    </div>
  );
};

export default ProductionChart;
